/**
 * Starts the EXPRESS-012 app on a real port so you can send requests by hand.
 * Run: npm run dev:express:12   (restarts on every save, which also resets the notes)
 * Do not edit this file; write your solution in task12.ts.
 */
import type { NextFunction, Request, Response } from "express";
import { createApp, type Note } from "./task12";

const PORT = Number(process.env.PORT ?? 3000);

const sampleNotes: Note[] = [
  { id: "n1", ownerId: "u-alice", title: "Alice private", body: "secret", visibility: "private", createdAt: "2026-03-01T10:00:00.000Z", updatedAt: "2026-03-01T10:00:00.000Z" },
  { id: "n2", ownerId: "u-alice", title: "Alice team", body: "shared", visibility: "team", createdAt: "2026-03-01T10:01:00.000Z", updatedAt: "2026-03-01T10:01:00.000Z" },
  { id: "n3", ownerId: "u-bob", title: "Bob private", body: "bob secret", visibility: "private", createdAt: "2026-03-01T10:02:00.000Z", updatedAt: "2026-03-01T10:02:00.000Z" },
  { id: "n4", ownerId: "u-bob", title: "Bob team", body: "bob shared", visibility: "team", createdAt: "2026-03-01T10:03:00.000Z", updatedAt: "2026-03-01T10:03:00.000Z" },
];

const app = createApp(sampleNotes);

// Runs only for errors your code does not handle itself: prints the full error
// in this terminal and returns it in the response, so a 500 shows what broke.
app.use((err: unknown, req: Request, res: Response, _next: NextFunction) => {
  console.error(`\n500 on ${req.method} ${req.originalUrl}\n`, err);
  const message = err instanceof Error ? err.message : String(err);
  res.status(500).json({ unhandledError: message });
});

app.listen(PORT, () => {
  console.log(`EXPRESS-012 running on http://localhost:${PORT} with notes n1 … n4`);
  console.log("Tokens: token-alice, token-bob, token-root (admin)");
  console.log("Send requests from src/express/task12/requests.http");
});
